class Cell {
    int value;
    Cell(int value) { this.value = value; }
    int read() { return this.value; }
}
int visit(int value) {
    Cell cell = new Cell(value);
    return cell.read();
}
void main() {
    int i = 0;
    long checksum = 0L;
    while (i < 1000000) {
        checksum = checksum + (long)visit(i);
        i = i + 1;
    }
    println(checksum);
}

