#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define BLOCKS 64u
#define LENGTH 4096u
#define ITERATIONS 200000u

static unsigned char haystack[BLOCKS][LENGTH];

__attribute__((noinline, optimize("no-tree-vectorize")))
static ptrdiff_t scalar_find(const unsigned char *p, size_t n, unsigned char needle) {
    for (size_t i = 0; i < n; ++i) {
        if (p[i] == needle) return (ptrdiff_t)i;
    }
    return -1;
}

int main(void) {
    for (size_t block = 0; block < BLOCKS; ++block) {
        memset(haystack[block], 'a', LENGTH);
        haystack[block][LENGTH - 1] = 0x7f;
    }
    uint64_t checksum = 0;
    for (uint32_t i = 0; i < ITERATIONS; ++i) {
        size_t block = (i * 17u + 11u) & (BLOCKS - 1u);
#ifdef SCALAR
        ptrdiff_t found = scalar_find(haystack[block], LENGTH, 0x7f);
#else
        const unsigned char *match = memchr(haystack[block], 0x7f, LENGTH);
        ptrdiff_t found = match == NULL ? -1 : match - haystack[block];
#endif
        if (found != (ptrdiff_t)(LENGTH - 1u)) return 2;
        checksum += (uint64_t)found + 1u;
    }
    printf("checksum=%" PRIu64 "\n", checksum);
    return 0;
}

