interface Work {
    int run(int value);
}
class Worker implements Work {
    public int run(int value) {
        if ((value % 997) == 0) { return value + 17; }
        return value + 3;
    }
}
void main() {
    Work worker = new Worker();
    int i = 0;
    long checksum = 0L;
    while (i < 200000000) {
        checksum = checksum + (long)worker.run(i);
        i = i + 1;
    }
    println(checksum);
}
